document.querySelectorAll('[data-event-gallery]').forEach(root=>{const items=JSON.parse(root.dataset.eventGallery),main=root.querySelector('[data-speaker-photo]'),image=main.querySelector('img'),thumbs=[...root.querySelectorAll('[data-event-index]')];let current=0;function select(index){current=(index+items.length)%items.length;const item=items[current];image.src=item.src;image.alt=item.caption;main.dataset.speakerPhoto=item.src;main.dataset.caption=item.caption;main.setAttribute('aria-label','Enlarge '+item.caption);root.querySelector('.event-photo-count').textContent=(current+1)+' / '+items.length;thumbs.forEach((t,i)=>t.setAttribute('aria-pressed',String(i===current)))}thumbs.forEach(t=>t.addEventListener('click',()=>select(Number(t.dataset.eventIndex))));root.querySelector('[data-event-prev]').addEventListener('click',()=>select(current-1));root.querySelector('[data-event-next]').addEventListener('click',()=>select(current+1))});